function stopTimer(){if(state.timer){clearInterval(state.timer);state.timer=null}}
function updateTimer(){const el=$("timerValue");if(!el)return;el.textContent=`${String(Math.floor(state.seconds/60)).padStart(2,"0")}:${String(state.seconds%60).padStart(2,"0")}`}
function startTimer(){stopTimer();updateTimer();state.lastSavedAt=Date.now();state.timer=setInterval(()=>{if(state.seconds<=0){stopTimer();state.finalized=true;saveProgress();showOutcome(t("timeout"),t("solution"));return}state.seconds--;updateTimer();if(state.seconds%2===0)saveProgress()},1000)}
function roomEdge(el,r,c){const cell=cellAt(r,c),id=cell.roomId,top=r>0?cellAt(r-1,c)?.roomId:null,bottom=r<state.level.rows-1?cellAt(r+1,c)?.roomId:null,left=c>0?cellAt(r,c-1)?.roomId:null,right=c<state.level.cols-1?cellAt(r,c+1)?.roomId:null;if(id!==top||id!==bottom||id!==left||id!==right)el.classList.add("room-edge");if(r===0||c===0||r===state.level.rows-1||c===state.level.cols-1)el.classList.add("house-edge")}
function victimCell(){const{rows,cols}=used(),n=state.level.activeCharacters.length;if(rows.size!==n||cols.size!==n)return null;const fr=[...Array(state.level.rows).keys()].find(r=>!rows.has(r)),fc=[...Array(state.level.cols).keys()].find(c=>!cols.has(c));if(fr==null||fc==null)return null;const cell=cellAt(fr,fc);return cell&&!blocked(cell)?key(fr,fc):null}
