function clueText(cl){
 const ch=findChar(cl.character).name[lang];
 const room=cl.room?state.level.rooms.find(r=>r.id===cl.room)?.name[lang]||"":"";
 const objKey=cl.on||cl.adj||cl.not_adj;
 const obj=objKey?OBJECTS[objKey]?.name[lang]||"":"";
 const parts=[];
 if(cl.row!=null&&cl.col!=null){
  if(lang==="ru") parts.push(`Я был в ${cl.row+1}-й строке и ${cl.col+1}-м столбце.`);
  else if(lang==="uk") parts.push(`Я був у ${cl.row+1}-му рядку та ${cl.col+1}-му стовпці.`);
  else parts.push(`I was in row ${cl.row+1}, column ${cl.col+1}.`);
 }else if(cl.row!=null){
  if(room){
   if(lang==="ru") parts.push(`Я был в ${cl.row+1}-й строке комнаты "${room}".`);
   else if(lang==="uk") parts.push(`Я був у ${cl.row+1}-му рядку кімнати "${room}".`);
   else parts.push(`I was in row ${cl.row+1} of the ${room}.`);
  }else if(lang==="ru") parts.push(`Я был в ${cl.row+1}-й строке.`);
  else if(lang==="uk") parts.push(`Я був у ${cl.row+1}-му рядку.`);
  else parts.push(`I was in row ${cl.row+1}.`);
 }else if(cl.col!=null){
  if(room){
   if(lang==="ru") parts.push(`Я был в ${cl.col+1}-м столбце комнаты "${room}".`);
   else if(lang==="uk") parts.push(`Я був у ${cl.col+1}-му стовпці кімнати "${room}".`);
   else parts.push(`I was in column ${cl.col+1} of the ${room}.`);
  }else if(lang==="ru") parts.push(`Я был в ${cl.col+1}-м столбце.`);
  else if(lang==="uk") parts.push(`Я був у ${cl.col+1}-му стовпці.`);
  else parts.push(`I was in column ${cl.col+1}.`);
 }else if(cl.room){
  if(lang==="ru") parts.push(`Я находился в комнате "${room}".`);
  else if(lang==="uk") parts.push(`Я був у кімнаті "${room}".`);
  else parts.push(`I was in the ${room}.`);
 }
 if(cl.on){
  if(lang==="ru") parts.push(`Я находился на объекте "${obj}".`);
  else if(lang==="uk") parts.push(`Я був на об’єкті "${obj}".`);
  else parts.push(`I was on the ${obj.toLowerCase()}.`);
 }else if(cl.adj){
  if(lang==="ru") parts.push(`Я находился рядом с объектом "${obj}".`);
  else if(lang==="uk") parts.push(`Я був поруч із об’єктом "${obj}".`);
  else parts.push(`I was next to the ${obj.toLowerCase()}.`);
 }else if(cl.not_adj){
  if(lang==="ru") parts.push(`Я не находился рядом с объектом "${obj}".`);
  else if(lang==="uk") parts.push(`Я не був поруч із об’єктом "${obj}".`);
  else parts.push(`I was not next to the ${obj.toLowerCase()}.`);
 }
 return `${ch}: ${parts.length?`«${parts.join(" ") }»`:"…"}`;
}
