function tutorialBoard(size=5, opts={}){
 const {pieceAt=[], blocked=[], highlighted=[], labels={}}=opts;
 let out='';
 for(let r=0;r<size;r++) for(let c=0;c<size;c++){
   const key=`${r},${c}`; const cls=[];
   if(blocked.includes(key)) cls.push('blocked');
   if(highlighted.includes(key)) cls.push('highlighted');
   const content=pieceAt.find(x=>x.pos===key)?.label||labels[key]||'';
   out+=`<span class="scene-cell ${cls.join(' ')}">${content}</span>`;
 }
 return `<div class="scene-board" style="--n:${size}">${out}</div>`;
}
function archiveTutorialVisual(step){
 const cyan='var(--cyan)', lime='var(--lime)', pink='var(--pink)', bad='var(--bad)', yellow='var(--yellow)';
 if(step===0) return `<div class="how-visual archive-visual tutorial-scene scene-select"><div class="scene-stage"><div class="scene-character-card"><div class="scene-avatar" style="--c:${cyan}">Б</div><div><b>${esc(findChar("bertram").name[lang]).toUpperCase()}</b><small>${esc(t("suspectSingle"))}</small></div></div><div class="scene-arrow">→</div>${tutorialBoard(4,{highlighted:['1,1'],pieceAt:[{pos:'1,1',label:'Б'}]})}<div class="scene-caption">${esc(t("lesson1Text"))}</div></div></div>`;
 if(step===1) return `<div class="how-visual archive-visual tutorial-scene scene-lines"><div class="scene-stage"><div class="scene-rule-card"><span>1</span><b>${esc(t('lineText'))}</b></div>${tutorialBoard(5,{highlighted:['2,2'],pieceAt:[{pos:'2,2',label:'Б'}]})}<div class="scene-cross-row"></div><div class="scene-cross-col"></div><div class="scene-tag row">${esc(t('row'))} ×</div><div class="scene-tag col">${esc(t('col'))} ×</div><div class="scene-caption">${esc(t("lesson2Text"))}</div></div></div>`;
 if(step===2) return `<div class="how-visual archive-visual tutorial-scene"><div class="scene-stage"><div class="adj-grid"><span class="no">×</span><span class="yes">✓</span><span class="no">×</span><span class="yes">✓</span><span class="center">Б</span><span class="yes">✓</span><span class="no">×</span><span class="yes">✓</span><span class="no">×</span></div><div class="scene-caption"><b>${esc(t('near'))}</b> — ${esc(t("lesson3Text"))}</div></div></div>`;
 if(step===3) return `<div class="how-visual archive-visual tutorial-scene"><div class="scene-stage"><div class="notes-board">${tutorialBoard(4,{pieceAt:[{pos:'1,1',label:'Б'}],blocked:['0,1','1,0']})}<div class="note-pill bad">${esc(t("noteCannot"))}</div><div class="note-pill maybe">${esc(t("noteMaybe"))}</div><div class="note-pill ok">${esc(t("noteSure"))}</div></div><div class="scene-caption">${esc(t("lesson4Text"))}</div></div></div>`;
 if(step===4) return `<div class="how-visual archive-visual tutorial-scene"><div class="scene-stage"><div class="object-board"><div class="object-cell forbidden"><span>🔥</span><b>✕</b><small>${esc(t("objectForbidden"))}</small></div><div class="object-cell allowed"><span>🪑</span><b>✓</b><small>${esc(t("objectAllowed"))}</small></div><div class="object-cell empty"><span>·</span><b>✓</b><small>${esc(t("objectEmpty"))}</small></div></div><div class="scene-caption">${esc(t("lesson5Text"))}</div></div></div>`;
 if(step===5) return `<div class="how-visual archive-visual tutorial-scene"><div class="scene-stage"><div class="map-legend"><span class="legend-chip cyan">А</span> ${esc(t("mapOccupied"))}<div></div><span class="legend-chip bad">×</span> ${esc(t("mapExcluded"))}<div></div><span class="legend-chip lime">Б</span> ${esc(t("mapCandidate"))}</div>${tutorialBoard(4,{pieceAt:[{pos:'1,1',label:'А'},{pos:'2,2',label:'Б'}],blocked:['0,0','0,3','3,1']})}<div class="scene-caption">${esc(t("lesson6Text"))}</div></div></div>`;
 if(step===6) return `<div class="how-visual archive-visual tutorial-scene"><div class="scene-stage last-scene">${tutorialBoard(4,{blocked:['0,1','0,2','1,0','1,2','2,0','2,1','3,0','3,3'],highlighted:['3,2']})}<div class="scene-last-arrow">↙</div><div class="scene-last-badge">${esc(t('victim'))}<br><b>${esc(t("svgLastCell"))}</b></div><div class="scene-caption">${esc(t("lesson7Text"))}</div></div></div>`;
 return `<div class="how-visual archive-visual tutorial-scene scene-final"><div class="scene-stage"><div class="final-title">${esc(t('win'))}</div>${tutorialBoard(5,{pieceAt:[{pos:'0,0',label:'Б'},{pos:'0,3',label:'В'},{pos:'1,1',label:'А'},{pos:'2,4',label:'Д'},{pos:'3,2',label:'Г'},{pos:'4,4',label:'☠'}]})}<div class="final-callout victim"><span>☠</span><b>${esc(t('victim'))}</b><small>${esc(t("finalVictim"))}</small></div><div class="final-callout culprit"><span>А</span><b>${esc(t('culprit'))}</b><small>${esc(t("finalCulprit"))}</small></div><div class="final-arrow">А → ${esc(t('culprit'))}</div></div></div>`;
}
function openHow(){let tip=0;const tips=[
 {title:t('lesson1Title'),text:t('lesson1Text')},
 {title:t('lesson2Title'),text:t('lesson2Text')},
 {title:t('lesson3Title'),text:t('lesson3Text')},
 {title:t('lesson4Title'),text:t('lesson4Text')},
 {title:t('lesson5Title'),text:t('lesson5Text')},
 {title:t('lesson6Title'),text:t('lesson6Text')},
 {title:t('lesson7Title'),text:t('lesson7Text')},
 {title:t('lesson8Title'),text:t('lesson8Text'),final:true}
];
 const render=()=>{const x=tips[tip];return `<div class="archive-tutorial"><div class="hint-progress"><span>${tip+1}/8</span><div><i style="width:${((tip+1)/8)*100}%"></i></div></div><div class="how-focus archive-focus"><div class="how-visual-wrap">${archiveTutorialVisual(tip)}</div><div class="hint-copy"><div class="hint-kicker">${esc(t("step"))} ${tip+1}</div><h3>${esc(x.title)}</h3><p>${esc(x.text)}</p>${x.final?`<div class="final-legend"><span class="legend-victim">☠ ${esc(t('victim'))}</span><span class="legend-culprit">● ${esc(t('culprit'))}</span></div>`:''}</div></div><div class="hint-actions"><button class="secondary" id="hintPrev" ${tip===0?'disabled':''}>${esc(t('prevHint'))}</button><button class="primary" id="hintNext">${esc(tip===7?t('close'):t('nextHint'))}</button></div></div>`};
 ruleModal(t('howTitle'),render());const modal=document.querySelector('.modal-bg:last-child');const draw=()=>{modal.querySelector('.modal').innerHTML=`<button class="close">×</button><div class="eyebrow">${esc(t('howTitle'))}</div><h2>${esc(t('howTitle'))}</h2>${render()}`;modal.querySelector('.close').onclick=()=>modal.remove();modal.querySelector('#hintPrev')?.addEventListener('click',()=>{tip=Math.max(0,tip-1);draw()});modal.querySelector('#hintNext')?.addEventListener('click',()=>{if(tip===7){modal.remove();return}tip++;draw()})};draw();
}

